from pathlib import Path
import json
p=Path('index.html'); s=p.read_text(encoding='utf-8')
data=json.loads(Path('content-before.json').read_text(encoding='utf-8'))
groups=data['groups']; quiz=data['quiz']; changes=[]
def cat(title):
 return next(c for g in groups for c in g['cats'] if c['title']==title)
def item(title,name,value=None,newname=None):
 c=cat(title); a=next(i for i in c['items'] if i[0]==name); old=a[:]
 if value is not None:a[1]=value
 if newname:a[0]=newname
 if a!=old:changes.append({'category':title,'before':old,'after':a[:]})
def title(old,new):
 cat(old)['title']=new; changes.append({'before':old,'after':new})
def qfix(topic,index,q=None,a=None):
 pair=next(c for c in quiz if c['name']==topic)['qs'][index]; old=pair[:]
 if q:pair[0]=q
 if a:pair[1]=a
 changes.append({'category':topic,'before':old,'after':pair[:]})
